static inline int servo_rf_predict(const float *x) {
  int votes[SERVO_RF_CLASSES] = {0};
  for (int t=0;t<SERVO_RF_TREES;t++) { int n=0;
    for (int step=0;step<SERVO_RF_MAX_NODES;step++) { const ServoNode *p=&SERVO_RF[t][n];
      if (p->prediction>=0) { votes[p->prediction]++; break; }
      n = (x[p->feature] <= p->threshold) ? p->left : p->right;
    }
  }
  int best=0; for(int c=1;c<SERVO_RF_CLASSES;c++) if(votes[c]>votes[best]) best=c; return best;
}
